//! Node addons built by napi: the loaders requiring the addon, committed or generated by the build script, linked to the Rust crate behind them.

mod test_project;

use prober_core::config::InferenceSettings;
use prober_core::graph::EdgeKind;

use crate::test_project::{TestProject, dependents, modified, selected};

const LOADER: &str = r#"
const { existsSync } = require('node:fs')

function requireNative() {
  if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
    return require(process.env.NAPI_RS_NATIVE_LIBRARY_PATH)
  }

  if (process.platform === 'darwin') {
    return require('./app.darwin-arm64.node')
  }

  try {
    return require('./app.linux-x64-gnu.node')
  } catch {
    return require('@app/binding-linux-x64-gnu')
  }
}

module.exports = requireNative()
"#;

fn committed_loader() -> TestProject {
    TestProject::new(&[
        (
            "package.json",
            r#"{ "name": "root", "workspaces": ["crates/node", "packages/*"] }"#,
        ),
        (
            "crates/node/package.json",
            r#"{ "name": "@app/binding", "main": "binding.js", "napi": { "binaryName": "app" } }"#,
        ),
        (
            "crates/node/Cargo.toml",
            "[package]\nname = \"app-node\"\n\n[lib]\ncrate-type = [\"cdylib\"]\n",
        ),
        ("crates/node/src/lib.rs", "pub fn run() {}\n"),
        ("crates/node/binding.js", LOADER),
        ("packages/core/package.json", r#"{ "name": "core" }"#),
        (
            "packages/core/src/compiler.ts",
            "import binding from \"@app/binding\";\n\nexport const run = () => binding.run();\n",
        ),
        (
            "packages/core/src/format.ts",
            "export const format = String;\n",
        ),
        (
            "packages/core/test/compiler.test.ts",
            "import { run } from \"../src/compiler\";\n\ntest(\"run\", () => run());\n",
        ),
        (
            "packages/core/test/format.test.ts",
            "import { format } from \"../src/format\";\n\ntest(\"format\", () => format(1));\n",
        ),
    ])
}

#[test]
fn committed_loader_requiring_the_addon_links_to_its_crate() {
    let graph = committed_loader().link();

    assert_eq!(
        dependents(&graph, "crates/node/Cargo.toml"),
        [("crates/node/binding.js", EdgeKind::Binding)]
    );
}

#[test]
fn a_crate_change_selects_the_tests_reaching_the_loader_without_widening() {
    assert_eq!(
        committed_loader().outcome_of(&[], &[modified("crates/node/Cargo.toml")]),
        selected(&[(
            "packages/core/test/compiler.test.ts",
            &[
                "crates/node/Cargo.toml (modified)",
                "-> loaded by crates/node/binding.js (inferred Node binding app (crates/node/package.json))",
                "-> imported by packages/core/src/compiler.ts",
                "-> imported by packages/core/test/compiler.test.ts",
            ],
        )])
    );
    assert_eq!(
        committed_loader().outcome_of(&[], &[modified("packages/core/src/format.ts")]),
        selected(&[(
            "packages/core/test/format.test.ts",
            &[
                "packages/core/src/format.ts (modified)",
                "-> imported by packages/core/test/format.test.ts",
            ],
        )])
    );
}

#[test]
fn loader_generated_by_the_build_script_links_its_importers_to_the_crate() {
    let project = TestProject::new(&[
        (
            "nodejs/package.json",
            r#"{ "name": "db", "napi": { "binaryName": "db" }, "scripts": { "build": "napi build --platform --js ../lib/native.js --output-dir lib && tsc" } }"#,
        ),
        ("nodejs/Cargo.toml", "[package]\nname = \"db-node\"\n"),
        ("nodejs/src/lib.rs", "pub fn open() {}\n"),
        (
            "nodejs/lib/table.ts",
            "import { Table } from \"./native\";\n\nexport const open = () => new Table();\n",
        ),
        (
            "nodejs/__test__/table.test.ts",
            "import { open } from \"../lib/table\";\n\ntest(\"open\", () => open());\n",
        ),
    ]);

    assert_eq!(
        dependents(&project.link(), "nodejs/Cargo.toml"),
        [("nodejs/lib/native.js", EdgeKind::Binding)]
    );
    assert_eq!(
        project.outcome_of(&[], &[modified("nodejs/Cargo.toml")]),
        selected(&[(
            "nodejs/__test__/table.test.ts",
            &[
                "nodejs/Cargo.toml (modified)",
                "-> loaded by nodejs/lib/native.js (inferred Node binding db (nodejs/package.json))",
                "-> imported by nodejs/lib/table.ts",
                "-> imported by nodejs/__test__/table.test.ts",
            ],
        )])
    );
}

#[test]
fn bindings_switched_off_leave_the_loader_unlinked_and_its_override_unresolved() {
    let graph = committed_loader().link_with(InferenceSettings {
        bindings: false,
        ..InferenceSettings::default()
    });
    let unresolved: Vec<String> = graph
        .unresolved_sites()
        .iter()
        .map(|site| format!("{}:{}", graph.path(site.file), site.line))
        .collect();

    assert_eq!(dependents(&graph, "crates/node/Cargo.toml"), []);
    assert_eq!(unresolved, ["crates/node/binding.js:6"]);
    assert!(committed_loader().link().unresolved_sites().is_empty());
}
